403	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
404	{
405	    (void) id;
406	    size_t n = qemu_plugin_tb_n_insns(tb);
407	
408	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
409	    // TB-start vaddr). Same id is shared by every insn in the TB.
410	    uint64_t bb_id = 0;
411	    if (bbv_mode && n > 0) {
412	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
413	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
414	    }
415	
416	    for (size_t i = 0; i < n; i++) {
417	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
418	
419	        // F14 count tick: registered FIRST so the count is incremented
420	        // before any trigger callback can call exit(200). NO_REGS keeps
421	        // the per-insn cost minimal (a single uint64 add).
422	        if (drain_at_exit_mode) {
423	            qemu_plugin_register_vcpu_insn_exec_cb(
424	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
425	        }
426	
427	        // BBV callback is registered BEFORE icount so that if both modes
428	        // fire on the same insn (icount target == slice multiple), the
429	        // slice row is emitted before exit(200) is called.
430	        if (bbv_mode) {
431	            qemu_plugin_register_vcpu_insn_exec_cb(
432	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
433	                GUINT_TO_POINTER((guint) bb_id));
434	        }
435	
436	        // Slice-consume callback (F11). Registered after BBV so a BBV
437	        // row at the same boundary is flushed first; ordering vs icount
438	        // is irrelevant (both drain).
439	        if (slice_consume_mode) {
440	            HandoffSite *site = g_new0(HandoffSite, 1);
441	            site->kind  = HYBRID_HANDOFF_ENTER;
442	            site->vaddr = qemu_plugin_insn_vaddr(insn);
443	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
444	            qemu_plugin_register_vcpu_insn_exec_cb(
445	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
446	        }
447	
448	        if (icount_mode) {
449	            HandoffSite *site = g_new0(HandoffSite, 1);
450	            site->kind  = HYBRID_HANDOFF_ENTER;
451	            site->vaddr = qemu_plugin_insn_vaddr(insn);
452	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
453	            qemu_plugin_register_vcpu_insn_exec_cb(
454	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
455	        }
456	
457	        if (pc_mode) {
458	            // PC-trigger mode: vaddr-only match. qemu_plugin_insn_size lets
459	            // a future fixture park enter_pc on a compressed insn -- next-PC
460	            // is computed from the API-reported size, not assumed to be 4.
461	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
462	            HandoffSite *site = g_new0(HandoffSite, 1);
463	            site->kind  = HYBRID_HANDOFF_ENTER;
464	            site->vaddr = qemu_plugin_insn_vaddr(insn);
465	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
466	            qemu_plugin_register_vcpu_insn_exec_cb(
467	                insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
468	            continue;
469	        }
470	
471	        // CSR-trigger mode (default).
472	        size_t sz = qemu_plugin_insn_size(insn);
473	        if (sz != 4) continue;
474	        uint32_t raw = 0;
